def infer_transform(grid):
    h, w = len(grid), len(grid[0])
    points=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v != 0]
    if not points:
        return [row[:] for row in grid]
    features=[('row', lambda r,c:r), ('col',lambda r,c:c), ('sum',lambda r,c:r+c), ('diff',lambda r,c:r-c)]
    candidates=[]
    for order,(name,fn) in enumerate(features):
        vals=[fn(r,c) for r,c,v in points]
        span=max(vals)-min(vals)+1
        for p in range(1,span+1):
            mp={}; good=True
            for r,c,v in points:
                k=fn(r,c)%p
                if k in mp and mp[k]!=v:
                    good=False; break
                mp[k]=v
            if good:
                candidates.append((p,-len(mp),order,name,fn,mp))
                break
    if not candidates:
        return [row[:] for row in grid]
    p,_,_,name,fn,mp=min(candidates)
    return [[mp.get(fn(r,c)%p,0) for c in range(w)] for r in range(h)]
